CREATE DATABASE IF NOT EXISTS bugmap_ai CHARACTER SET utf8mb4; USE bugmap_ai;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','developer') DEFAULT 'developer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE projects(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,name VARCHAR(120) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE log_files(id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,filename VARCHAR(255),status ENUM('uploaded','parsed','failed') DEFAULT 'uploaded',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE error_groups(id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,label VARCHAR(255),event_count INT DEFAULT 0,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE error_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,log_file_id INT NOT NULL,group_id INT NULL,line_no INT,occurred_at DATETIME,level VARCHAR(10),source VARCHAR(120),message TEXT,stack_trace TEXT,INDEX(level),INDEX(occurred_at),FOREIGN KEY(log_file_id) REFERENCES log_files(id) ON DELETE CASCADE,FOREIGN KEY(group_id) REFERENCES error_groups(id) ON DELETE SET NULL);
CREATE TABLE ai_analyses(id INT AUTO_INCREMENT PRIMARY KEY,log_file_id INT NOT NULL,result_json JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(log_file_id) REFERENCES log_files(id) ON DELETE CASCADE);
CREATE TABLE alerts(id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,severity VARCHAR(10),message VARCHAR(255),acknowledged TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE reports(id INT AUTO_INCREMENT PRIMARY KEY,project_id INT NOT NULL,title VARCHAR(160),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(120),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
